#include <stdio.h>
int main(void) {
    double f = 600e6;     /* 600 MHz */
    double cpi = 2.0;
    double mips = f / (cpi * 1e6);
    double ic = 1.2e8;
    double t = ic * cpi / f;
    printf("主频 = 600 MHz\n");
    printf("CPI = 2.00\n");
    printf("MIPS = 主频 / (CPI * 1e6) = %.1f\n", mips);
    printf("若指令数 = 120000000, CPU 时间 = %.4f s\n", t);
    return 0;
}
